('Los tickets se obtienen de forma presencial en el Comedor, en la Facultad de Psicología y en la Puerta 1, o en línea por el Portal UNMSM. Sirve hasta 2,600 almuerzos por turno; a las largas colas se les llama "el gusaneo". Categoría: Servicios. Horario: Lun–Vie · Desayuno: 7:00 (Sin Ticket) · Almuerzo: 12:00–13:40 (Con Ticket) · Cena: 17:00–18:00 (Con Ticket). Horario detallado: Desayuno: 7:00'::text, '{"title": "Comedor Universitario", "place_id": "comedor-universitario", "position": 1, "document_id": "place-comedor-universitario"}'::jsonb, '[-0.00714194,-0.0048222165,0.048788674,-0.06159211,0.030120501,0.036614772,-0.0037637518,0.028091185,-0.00060625235,0.02535623,-0.028297385,0.019468162,-0.020968713,0.0029214094,0.1824735,0.027185533,-0.009750455,-0.019033886,-0.025515014,-0.03729179,0.017191755,-0.048163313,-0.0023237732,0.034479372,-0.022353942,0.02122178,0.045110513,-0.04954398,0.046355132,0.0117291,-0.022933686,0.050491996,-0.024510566,-0.01723034,-0.010483296,-0.035494942,0.0086160125,-0.04390207,-0.026675632,0.019386763,0.016096897,0.012661719,0.020449566,0.039422464,0.013650596,-0.017634733,-0.008124363,-0.06904229,0.0008837839,-0.0054213335,0.0011219173,-0.0012411224,-0.015255335,-0.2975035,0.0044271704,0.029432071,-0.009535732,-0.006873067,-0.018203532,-0.06364986,-0.07483591,0.013291486,-0.031064974,0.0028850103,0.020083126,0.020975243,0.047195215,0.098904,0.0038882378,-0.021114513,0.0073109404,-0.03393008,-0.019564755,-0.0073823766,-0.009469461,0.012293089,-0.031790897,0.024785811,-0.035107996,-0.0011283353,-0.007845795,0.007558926,0.012244945,-0.020907817,0.027384771,0.009687506,-0.011664939,-0.0065750093,-0.0077439407,0.0018904932,-0.022522036,0.02894637,0.02981075,-0.09857247,0.036476053,0.024026683,0.0068455487,-0.014825734,-0.04606472,-0.066539,-0.04473406,0.0345587,0.015748193,0.056084506,0.029312525,-0.07161341,0.02096528,0.011307006,0.0073069595,0.018077686,0.009628635,0.058201592,0.015257483,0.007915906,-0.003613581,-0.26982442,0.018416073